events.command:
/bin/bash -lc "find . -maxdepth 2 -type f -printf '%p\\n' | sort && printf '\\nTools:\\n' && command -v ffmpeg && command -v python3 && python3 - <<'PY'
mods=['cv2','PIL','numpy','imageio']
for m in mods:
 try:
  x=__import__(m); print(m,'ok',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',e)
PY"

/bin/bash -lc "type -a python3 || true; type -a ffmpeg || true; ls /usr/bin/python* 2>/dev/null | head; python3 - <<'PY'
mods=['cv2','PIL','numpy','imageio']
for m in mods:
 try:
  x=__import__(m); print(m,'ok',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',repr(e))
PY"
